def qsec(n):
    m = re.search(r"^## %d\. .*?(?=^## \d+\. |\Z)" % n, quotes, re.S | re.M)
    return m.group(0).strip()

def fsec(text, heading):
    m = re.search(r"^## %s.*?(?=^## |\Z)" % re.escape(heading), text, re.S | re.M)
    return m.group(0).strip()

def fline(text, prefix):
    return "\n".join(l for l in text.splitlines() if l.startswith(prefix))

